"""Short original concept cards used in the guided course and reference notebook."""
def add_study_cards(chapters):
    def card(title, text, example, question, options, correct, explanation):
        return dict(title=title, text=text, example=example, quiz=dict(question=question, options=options, correct=correct, explanation=explanation, code=example))
    cards = {
    'baze': [
        card('Obiecte, nume și tipuri', 'Un nume referă un obiect. Obiectul are identitate, tip și valoare. Atribuirea nu copiază automat obiectul; tipul aparține obiectului, nu unui nume fix. int și str sunt clase, iar None reprezintă absența unei valori.', 'a = [1]\nb = a\nprint(a == b, a is b)\nprint(type(a).__name__)', 'În Python, ce verifică expresia a is b?', ['Identitatea obiectului', 'Numai egalitatea valorilor', 'Tipul variabilei'], 0, 'Două liste distincte pot fi egale prin == și diferite prin is.'),
        card('Operatori și priorități', 'Parantezele fac intenția clară. Puterea ** se asociază la dreapta: 2**3**2 este 2**(3**2). // rotunjește câtul spre minus infinit; a=b*(a//b)+a%b. Operatorii pe biți lucrează pe reprezentarea întreagă, iar and/or lucrează cu adevărul valorilor.', 'print(2 ** 3 ** 2)\nprint(-7 // 3, -7 % 3)', 'Ce produce -7 // 3 în Python?', ['-2', '-3', '3'], 1, 'Câtul este rotunjit în jos, spre minus infinit.'),
        card('Evaluare cu scurtcircuit', 'and nu evaluează restul după o valoare falsă; or se oprește după una adevărată. Ele returnează un operand, nu obligatoriu bool. O comparație înlănțuită precum 0<=x<10 exprimă ambele limite.', 'x = 0\nprint(x != 0 and 10 / x > 1)\nprint("" or "implicit")', 'Pentru x = 0, de ce expresia x != 0 and 10 / x > 1 nu produce ZeroDivisionError?', ['and oprește evaluarea', 'Python ignoră toate împărțirile', '0 devine 1'], 0, 'Primul operand este fals, deci al doilea nu mai este evaluat.')],
    'decizii': [
        card('Condiții și cazuri de graniță', 'if/elif/else execută prima ramură adevărată. == compară și = atribuie. Testează limitele: 0, egalitate, prima și ultima valoare admisă. Pentru o dată calendaristică, luna și anul determină intervalul valid al zilei.', 'an = 1900\nbisect = an % 400 == 0 or an % 4 == 0 and an % 100 != 0\nprint(bisect)', 'Conform regulii calendarului gregorian din exemplu, este anul 1900 bisect?', ['Da', 'Nu'], 1, 'Este divizibil cu 100, dar nu cu 400.'),
        card('Ramuri și indentare', 'Corpul unei ramuri este delimitat prin indentare. Un elif aparține aceluiași lanț; două if separate pot executa două corpuri. Într-un calculator simplu, validează operatorul și numitorul înainte de împărțire.', 'x = 3\nif x > 0:\n    print("pozitiv")\nif x % 2:\n    print("impar")', 'Pentru x = 3, câte linii afișează programul cu cele două instrucțiuni if independente?', ['Unul', 'Două', 'Niciunul'], 1, 'Cele două if independente pot avea ambele condiții adevărate.')],
    'bucle': [
        card('for, while și valori santinelă', 'for consumă elementele unui iterabil; range exclude limita finală. while repetă cât timp condiția este adevărată. Actualizează starea care controlează oprirea. O santinelă încheie citirea fără să intre în calcul.', 's = 0\nx = int(input())\nwhile x != 0:\n    s += x\n    x = int(input())\nprint(s)', 'În programul dat, valoarea 0 oprește citirea. Este ea prelucrată de instrucțiunea s += x?', ['Da', 'Nu'], 1, 'Ea semnalează oprirea și nu este procesată.'),
        card('break, continue și else', 'break termină cea mai apropiată buclă; continue trece la următoarea iterație. else atașat unui for sau while se execută la terminarea normală, inclusiv pentru zero iterații. Nu se execută la ieșirea prin break, return sau o excepție care părăsește bucla.', 'for x in [2, 4, 6]:\n    if x % 2:\n        break\nelse:\n    print("toate pare")', 'În Python, când se execută blocul else atașat unei bucle for sau while?', ['La orice iterație', 'Când bucla se termină normal, fără întrerupere prin break', 'Numai când apare break'], 1, 'La for, else se execută după parcurgerea completă; la while, când condiția devine falsă. Se execută și pentru zero iterații. Un break, un return care părăsește funcția sau o excepție care părăsește bucla îl împiedică. else este aliniat cu bucla, nu cu if.'),
        card('Invariante și acumulatoare', 'Un invariant descrie ce este deja corect înaintea fiecărui pas. Pentru suma unui prefix, s conține suma elementelor procesate. Suma pornește de la 0, produsul de la 1; minimul unei liste nevide pornește dintr-un element real.', 's = 0\nfor x in [3, -1, 2]:\n    s += x\nprint(s)', 'După prelucrarea valorilor 3 și -1 din lista dată, ce valoare are acumulatorul s?', ['Suma lor, 2', 'Ultimul element, -1', 'Lungimea listei'], 0, 'Invariantul este suma prefixului deja parcurs.')],
    'siruri': [
        card('Feliere cu pas și imutabilitate', 's[start:stop:step] exclude stop și acceptă indici negativi; un pas negativ parcurge invers. Șirul nu poate fi modificat prin atribuirea unui caracter. Metodele creează alte șiruri. Nu folosi is pentru a compara texte: interning este un detaliu de implementare.', 's = "abcdef"\nprint(s[1:5:2])\nprint(s[::-1])', 'Pentru s = "abcdef", ce text afișează print(s[1:5:2])?', ['bd', 'bdf', 'ace'], 0, 'Sunt selectate pozițiile 1 și 3; poziția 5 este exclusă.'),
        card('find, index și replace', 'find returnează -1 la lipsă, index ridică ValueError. count și replace tratează apariții fără suprapunere; replace acceptă un număr maxim de înlocuiri. Un subșir nu este obligatoriu un cuvânt întreg.', 'print("aaaa".find("z"))\nprint("aaaa".replace("aa", "x", 1))', 'Ce returnează metoda str.find() când subșirul căutat nu apare în șir?', ['0', '-1', 'None'], 1, 'index ar produce o excepție, dar find returnează -1.'),
        card('Validare și formatare', 'strip elimină caracterele de la margini, split fără argument separă după grupuri de whitespace, join unește elementele. isdigit/isalpha/isupper au reguli pentru Unicode, nu doar ASCII. center, ljust, rjust și format permit alinierea. f-string poate controla zecimalele și lățimea.', 'print(f"{3.5:.2f}")\nprint("x".center(5, "."))\nprint("-".join("a  b".split()))', 'Care este rezultatul lui f"{3.5:.2f}"?', ['3.5', '3.50', '3'], 1, 'Formatarea cere exact două zecimale.')],
    'liste': [
        card('Metode și modificări în loc', 'append adaugă un obiect, extend adaugă elementele unui iterabil, insert schimbă indicii următori. pop elimină și returnează; remove elimină prima valoare și poate ridica eroare. del și atribuirea unei felii pot schimba lungimea. sort/reverse modifică lista și returnează None.', 'a = [1, 2]\na.extend([3, 4])\ndel a[1:3]\nprint(a)', 'După extend și del din exemplu, care este conținutul listei a?', ['[1, 4]', '[1, 2, 3, 4]', '[2, 3]'], 0, 'Felie 1:3 elimină elementele de pe pozițiile 1 și 2.'),
        card('Referințe și copie în adâncime', 'b=a creează un alt nume pentru același obiect. a.copy() copiază numai containerul exterior; obiectele imbricate rămân partajate. deepcopy copiază recursiv. [[0]*m]*n repetă aceeași linie; construiește fiecare linie separat.', 'a = [[1], [2]]\nb = a.copy()\nb[0].append(9)\nprint(a)', 'În exemplu, a.copy() creează și copii independente ale listelor interioare?', ['Da', 'Nu'], 1, 'a[0] și b[0] se referă în continuare la aceeași listă.'),
        card('Tupluri și despachetare extinsă', 'Tuplul este o secvență imutabilă; o listă aflată în el poate totuși fi modificată. Virgula formează tuplul cu un element: (3,). La despachetare, *rest colectează elementele suplimentare într-o listă.', 'primul, *mijloc, ultimul = (1, 2, 3, 4)\nprint(primul, mijloc, ultimul)', 'După despachetarea primul, *mijloc, ultimul = (1, 2, 3, 4), ce tip are mijloc?', ['tuple', 'list', 'int'], 1, 'Ținta cu * colectează elementele într-o listă.'),
        card('Matrice și comprehensiuni', 'O matrice este o listă de linii. Comprehensiunea exprimă transformare și filtrare; ordinea buclelor ei este aceeași ca la bucle imbricate. Pentru prelucrări în loc, evită ștergerea în timp ce înaintezi fără să controlezi indicii.', 'a = [[i + j for j in range(3)] for i in range(2)]\nprint([max(row) for row in a])', 'Câte linii construiește comprehensiunea exterioară a matricei a din exemplu?', ['2', '3', '6'], 0, 'Comprehensiunea exterioară construiește câte o linie pentru fiecare i.')],
    'colectii': [
        card('Hashing, set și frozenset', 'O cheie hashable trebuie să aibă hash stabil și egalitate compatibilă cu hash-ul. int, str și tuplurile de valori hashable pot fi chei; listele și set-urile mutabile nu. Hash-uri egale nu dovedesc egalitatea: pot exista coliziuni. frozenset este o mulțime imutabilă hashable.', 'd = {frozenset("aab"): 1}\nprint(d[frozenset("ab")])', 'Poate o listă Python obișnuită, precum [1, 2], să fie cheie într-un dicționar?', ['Da', 'Nu'], 1, 'Listele sunt mutabile și nehashable.'),
        card('Operații și metode de mulțimi', '| reunește, & intersectează, - scade și ^ calculează diferența simetrică. <= verifică incluziunea. add/update inserează; remove ridică KeyError la lipsă, discard nu. Ordinea unui set nu este un format de ieșire garantat; sortează explicit.', 'a = {1, 2}\nb = {2, 3}\nprint(sorted(a ^ b))\na.discard(7)', 'Pentru a = {1, 2} și b = {2, 3}, ce valori conține a ^ b?', ['{1, 3}', '{2}', '{1, 2, 3}'], 0, 'Ea conține valorile din exact una dintre mulțimi.'),
        card('Dicționare imbricate și vizualizări', 'd[cheie] cere existența cheii; get acceptă o valoare implicită. setdefault poate inițializa un container; pop poate șterge cu valoare implicită. keys/values/items sunt vizualizări ale dicționarului. Pentru cinema sau elevi, alege cheia principală după interogările și actualizările cerute.', 'd = {}\nd.setdefault("Cinema 1", {})["Film"] = {"18:00"}\nprint(d["Cinema 1"]["Film"])', 'În dicționarul din exemplu, ce avantaj oferă folosirea numelui cinematografului drept cheie principală?', ['Acces direct la înregistrare', 'Eliminarea tuturor testelor', 'Sortare automată'], 0, 'Modelul datelor trebuie să susțină operațiile problemei.'),
        card('Sortare cu mai multe criterii', 'key întoarce criteriul; tuplurile se compară lexicografic. Pentru numere, semnul minus inversează un criteriu fără a inversa toate celelalte. Sortarea este stabilă: elementele cu chei egale își păstrează ordinea inițială. reverse inversează toate comparațiile cheii.', 'a = [("Ana", 9), ("Dan", 10), ("Eva", 9)]\na.sort(key=lambda x: (-x[1], x[0]))\nprint(a)', 'După sortarea listei a din exemplu după (-nota, nume), care este numele din primul element?', ['Ana', 'Dan', 'Eva'], 1, 'Nota este descrescătoare, apoi numele crescător.')],
    'functii': [
        card('Parametri: modificare versus reasignare', 'Parametrul local este un nume pentru obiectul transmis. Modificarea unei liste este vizibilă apelantului, reasignarea parametrului nu schimbă numele apelantului. return transmite o valoare; în lipsa lui funcția întoarce None.', 'def f(a):\n    a.append(3)\n    a = []\nx = [1]\nf(x)\nprint(x)', 'După apelul f(x) din exemplu, care este conținutul listei x?', ['[1, 3]', '[]', '[1]'], 0, 'append modifică obiectul original; a=[] reasignează numai parametrul local.'),
        card('args, kwargs și valori implicite', '*args colectează argumente poziționale într-un tuplu, **kwargs argumente numite într-un dict. Parametrii după * sunt keyword-only. Valorile implicite se evaluează la definire: o listă implicită poate fi partajată accidental. Folosește None și creează lista în corp.', 'def f(a, b=2, *args, c=3, **kwargs):\n    return a + b + c\nprint(f(1, c=4))', 'În definiția def f(a, b=2, *args, c=3, **kwargs), poate parametrul c să primească o valoare printr-un argument pozițional?', ['Da', 'Nu'], 1, 'c se află după *args și se transmite prin nume.'),
        card('Domeniul de vizibilitate', 'Căutarea unui nume urmează local, închideri, global, builtins. O atribuire face numele local dacă nu declari global/nonlocal. global se referă la modul; nonlocal la o legătură existentă într-o funcție exterioară. O închidere poate păstra starea după terminarea apelului exterior.', 'def contor():\n    n = 0\n    def pas():\n        nonlocal n\n        n += 1\n        return n\n    return pas', 'În funcția pas din exemplu, la ce variabilă n se referă declarația nonlocal n?', ['Variabila funcției exterioare', 'O variabilă de sistem', 'Un nou nume global'], 0, 'nonlocal cere o legătură existentă în domeniul exterior.'),
        card('Funcții ca valori și generatori', 'Funcțiile pot fi argumente, rezultate și chei de sortare; lambda definește o expresie anonimă. Recursivitatea are caz de bază și reducere. yield suspendă execuția și păstrează starea; next consumă o valoare, iar generatorul e epuizabil.', 'g = (x * x for x in range(3))\nprint(next(g))\nprint(list(g))', 'După un singur next(g), ce elemente conține lista produsă de list(g) în exemplu?', ['[0, 1, 4]', '[1, 4]', '[0]'], 1, 'Valoarea 0 a fost deja consumată.')],
    'fisiere': [
        card('Citire, moduri și memorie', 'r citește un fișier existent, w îl recreează/trunchiază, a adaugă la final, x cere un fișier nou, iar + permite citire și scriere. read citește tot, readline o linie, readlines toate liniile într-o listă. Iterarea procesează câte o linie și economisește memorie.', 'with open("date.in", encoding="utf-8") as f:\n    for line in f:\n        print(line.rstrip("\\n"))', 'La deschiderea reușită cu open(nume, "w"), ce se întâmplă cu textul deja existent în fișier?', ['Adaugă la final', 'Îl trunchiază', 'Nu îl modifică'], 1, 'w începe un fișier de ieșire nou, eliminând conținutul anterior.'),
        card('Context și excepții', 'with închide fișierul și dacă apare o eroare în bloc; nu face erorile să dispară. Prinde FileNotFoundError pentru fișier lipsă și ValueError la conversie, în zona potrivită. write nu adaugă newline; print(file=f) îl adaugă implicit.', 'try:\n    x = int("abc")\nexcept ValueError:\n    print("număr invalid")', 'Instrucțiunea with open(...) tratează automat o eroare FileNotFoundError, astfel încât execuția să continue fără un except?', ['Da', 'Nu'], 1, 'Gestionarea resursei și tratarea excepției sunt responsabilități diferite.'),
        card('Mai multe fișiere și date reproducibile', 'Separă citirea, prelucrarea și scrierea. Normalizează textele la fel înainte de frecvențe, altfel rezultatele nu sunt comparabile. În aplicație, fiecare fișier are un câmp propriu; la verificare, fiecare test primește un director nou.', 'from collections import Counter\na = Counter("mere pere mere".split())\nprint(a["mere"])', 'Ce avantaj are o funcție care calculează rezultatul fără să citească sau să afișeze date?', ['Pentru testare și reutilizare', 'Pentru a evita orice funcție', 'Pentru a impune o singură intrare'], 0, 'O funcție de calcul poate fi verificată fără citire din fișier.')],
    'module': [
        card('Translate și regex', 'maketrans poate înlocui ori șterge caractere; translate aplică tabela. Regex descrie tipare, nu toate regulile semantice. [0-9] este ASCII, iar \\d poate include alte cifre Unicode. Un model de dată poate accepta 99.99.9999; validarea calendaristică este separată.', 'import re\nprint(bool(re.fullmatch(r"[0-9]{2}\\.[0-9]{2}\\.[0-9]{4}", "99.99.9999")))', 'Dacă re.fullmatch din exemplu acceptă textul "99.99.9999", înseamnă că acesta reprezintă o dată calendaristică validă?', ['Da', 'Nu'], 1, 'Regex verifică forma; intervalele și calendarul se validează separat.'),
        card('compile, search, match, grupuri și sub', 'compile reutilizează un tipar. search caută oriunde, match numai la început, fullmatch pe tot șirul. group extrage grupuri, start/end dau intervalul cu end exclus. findall găsește potriviri, split separă, sub înlocuiește. Escapează caracterele speciale când vrei sens literal.', 'import re\nm = re.search(r"([A-Z]+)-([0-9]+)", "xx AB-12")\nprint(m.group(1), m.start(), m.end())', 'Pentru obiectul Match m din exemplu, m.end() indică poziția ultimului caracter inclus în potrivire?', ['Da', 'Nu'], 1, 'Intervalul unei potriviri este [start,end).'),
        card('Date, fusuri și suprapuneri', 'date, time și datetime reprezintă date și momente; timedelta o durată. strptime interpretează un format, strftime îl afișează. Compară momente complete pentru rezervări, inclusiv schimbarea zilei. Un datetime fără fus este naive; nu îl amesteca direct cu unul aware. Folosește o dată de referință fixă în teste.', 'from datetime import datetime, timedelta\nd = datetime(2024, 2, 28)\nprint(d + timedelta(days=2))', 'Câte zile trec de la 28 februarie 2024 la 1 martie?', ['1', '2', '3'], 1, '2024 este an bisect și februarie are 29 de zile.')],
    'complexitate': [
        card('Costul timpului și al memoriei', 'Definește dimensiunea intrării. Adună costurile etapelor; nu ignora citirea și sortarea. Bucle succesive O(n)+O(n) rămân O(n); bucle imbricate nu sunt mereu O(n²), fiindcă numărul total de mutări poate fi liniar. Analizează separat memoria și stiva recursivă.', 'n = 8\npasi = 0\nwhile n > 1:\n    n //= 2\n    pasi += 1', 'Considerând un cost constant pentru stocarea fiecărui întreg, ce memorie suplimentară folosește bucla din exemplu în funcție de valoarea inițială n?', ['O(1)', 'O(n)', 'O(n²)'], 0, 'Păstrează doar un număr constant de variabile.'),
        card('Operații ale colecțiilor', 'Căutarea în listă este O(n). Accesul prin indice este O(1); inserarea la început deplasează elemente și este O(n). append are cost amortizat O(1). Căutarea în set/dict este în medie O(1), dar coliziunile pot produce O(n) în caz nefavorabil. Sortarea generală are O(n log n).', 'a = [1, 2, 3]\nprint(3 in a)\ns = set(a)\nprint(3 in s)', 'Pentru un set Python cu n elemente, care este costul mediu al testului x in s, presupunând hash și comparații cu cost constant?', ['O(1)', 'O(n²)', 'O(log n) obligatoriu'], 0, 'Este cost mediu; nu o garanție pentru orice caz.'),
        card('Recurențe și clase de creștere', 'Pentru o singură jumătate: T(n)=T(n/2)+O(1), deci O(log n). Pentru două jumătăți și combinare liniară: 2T(n/2)+O(n), deci O(n log n). Recursia naivă Fibonacci repetă subprobleme și are cost exponențial. Unitățile de cost trebuie explicate, mai ales pentru întregi foarte mari.', 'def f(n):\n    if n <= 1:\n        return\n    f(n // 2)\n    f(n // 2)', 'În funcția f din exemplu, câte apeluri directe f(n // 2) execută un apel pentru care n > 1?', ['Unul', 'Două', 'n'], 1, 'Ambele jumătăți sunt rezolvate, nu numai una.')],
    'divide': [
        card('Împarte, rezolvă, combină', 'Precizează cazul direct, cum scade dimensiunea și cum combini rezultatele. Căutarea binară rezolvă o singură jumătate; merge sort le rezolvă pe ambele. Felierea copiază elemente: nu presupune că ea are cost constant.', 'def putere(a, n):\n    if n == 0:\n        return 1\n    p = putere(a, n // 2)\n    return p * p if n % 2 == 0 else p * p * a', 'În funcția putere din exemplu, de ce calculăm putere(a, n // 2) o singură dată și păstrăm rezultatul în p?', ['Pentru a evita două apeluri identice', 'Pentru sortare', 'Pentru a opri toate calculele'], 0, 'Recalcularea aceleiași jumătăți ar schimba recurența costului.'),
        card('Quickselect și BFPRT', 'Quickselect partiționează în <pivot, =pivot și >pivot și continuă în partea rangului căutat. Pivot aleator: O(n) în medie, O(n²) nefavorabil. BFPRT alege mediana medianelor unor grupuri de 5; reduce suficient partea mare pentru O(n) în cazul nefavorabil.', 'a = [5, 1, 3, 3, 9]\np = 3\nprint([x for x in a if x < p])\nprint([x for x in a if x == p])', 'În Quickselect, după partiționare, trebuie apelată recursiv selecția în ambele părți pentru a găsi un singur element de rang k?', ['Da', 'Nu'], 1, 'Rangul dorit se află într-o singură parte sau în zona egală pivotului.'),
        card('Mediane și partiționare', 'La două liste sortate, caută o separare în care jumătatea stângă conține numărul corect de valori și niciun element stâng nu depășește unul drept. Mediana ponderată folosește ponderea cumulată, nu numărul valorilor. Precizează convenția la exact jumătate.', 'a = [1, 3]\nb = [2, 4]\nprint((2 + 3) / 2)', 'Pentru listele a = [1, 3] și b = [2, 4], care este mediana celor patru valori reunite, folosind media celor două valori centrale?', ['2', '2.5', '3'], 1, 'Pentru lungime pară se face media celor două valori centrale.'),
        card('Cadrane și geometrie', 'O tablă 2^n se împarte în patru cadrane. La tromino, o piesă centrală creează câte o gaură pentru trei cadrane, păstrând condiția subproblemei. La dreptunghi fără găuri, încearcă tăieturi printr-o gaură; alte soluții optime pot avea coordonate diferite.', 'print(2 ** 3, 4 ** 3)', 'O tablă pătrată are latura 2**n celule. Pentru n = 3, câte celule are întreaga tablă?', ['8', '64', '32'], 1, 'Tabla are 8×8=64 celule.')],
    'greedy': [
        card('Demonstrație prin schimb', 'O alegere locală cere justificare. Pentru activități, înlocuiește primul interval al unei soluții optime cu cel care se termină mai devreme: restul rămâne fezabil. Repetând argumentul, obții optimul Greedy. Contraexemplele disting un criteriu bun de unul intuitiv dar greșit.', 'monede = [1, 3, 4]\nprint("Greedy pentru 6: 4+1+1; optim: 3+3")', 'Pentru suma 6 și monede nelimitate de valori 1, 3 și 4, alegerea repetată a celei mai mari monede posibile minimizează numărul monedelor?', ['Da', 'Nu'], 1, 'Are trei monede, iar soluția optimă are două.'),
        card('Planificări și reconstrucție', 'Durate mici mai întâi minimizează așteptarea totală neponderată. Pentru suma ponderată, sortează durată/prioritate. EDD ordonează după termen pentru întârziere maximă minimă. Joburile de durată 1 cu profit cer selecție; când duratele diferă, această regulă nu mai este suficientă.', 'a = [(3, 1), (1, 2)]\nprint(sorted(a, key=lambda x: x[0] / x[1]))', 'Regula EDD (Earliest Due Date) ordonează lucrările crescător după ce criteriu?', ['Profitul', 'Termenul limită', 'Culoarea'], 1, 'Earliest Due Date ordonează după cel mai apropiat termen.'),
        card('Heapq și PriorityQueue', 'Heapul minim permite accesul la minim în O(1) și inserare/extragere O(log n); heapify este O(n). heapq lucrează pe o listă și nu o sortează complet. queue.PriorityQueue oferă o interfață sincronizată cu put/get; pentru algoritmi locali heapq este adesea suficient.', 'import heapq\nh = [5, 2, 8]\nheapq.heapify(h)\nprint(heapq.heappop(h))', 'După heapq.heapify(h), elementele listei h sunt garantat ordonate complet crescător?', ['Da', 'Nu'], 1, 'Doar relația de heap este garantată, nu sortarea globală.'),
        card('Cuburi și situații speciale', 'Cu laturi distincte, sortarea descrescătoare permite alegerea celui mai mare cub din blocul unei culori. Cu laturi repetate, alegerile pot afecta continuarea și trebuie revizuită justificarea; DP poate calcula înălțimea și numărul turnurilor. Pentru joc cu număr par de elemente, paritatea pozițiilor oferă o strategie cu scor cel puțin egal.', 'a = [(10, 1), (9, 1), (8, 2), (5, 1)]\nprint(10 + 8 + 5)', 'Dacă o demonstrație Greedy pentru turnuri de cuburi presupune laturi distincte, poate fi aplicată automat, fără verificări, și când laturile se repetă?', ['Da', 'Nu'], 1, 'Ipotezele demonstrației trebuie reverificate.')],
    'dinamica': [
        card('Stări, recurențe și ordine', 'Definește sensul exact al dp înainte de cod. Arată ultima decizie a unei soluții optime și subproblema rămasă. Stabilește bazele și o ordine în care toate dependențele sunt cunoscute. Memoizarea de sus în jos și calculul de jos în sus evită repetarea subproblemelor.', 'dp = [0, 1]\nfor i in range(2, 6):\n    dp.append(dp[i - 1] + dp[i - 2])\nprint(dp[5])', 'În calculul iterativ al programării dinamice, de ce trebuie calculate întâi stările de care depinde starea curentă?', ['Dependența trebuie cunoscută', 'Pentru că lista nu poate crește', 'Pentru sortare'], 0, 'Ordinea trebuie să respecte relațiile de recurență.'),
        card('Reconstrucție și număr de optime', 'Valoarea optimă nu este soluția efectivă. Memorează predecesorul ori decizia; pornește din starea finală și revino spre bază. Pentru număr de soluții optime: la un optim mai bun înlocuiești numărul, la egalitate îl aduni, fără a dubla aceleași soluții.', 'best = [0, 3, 5]\npred = [-1, 0, 1]\ni = 2\nwhile i != -1:\n    print(i)\n    i = pred[i]', 'O nouă tranziție produce același optim și soluții distincte de cele deja numărate. Cum actualizezi numărul soluțiilor optime?', ['Îl aduni', 'Îl resetezi la 0', 'Ignori toate variantele'], 0, 'Soluțiile distincte din ramurile compatibile contribuie la același optim.'),
        card('Strict și nedescrescător', 'La LIS strict folosești <, la subșir nedescrescător ≤. Pentru O(n log n), tails păstrează cel mai mic final pentru fiecare lungime; el singur nu este obligatoriu o soluție în ordinea intrării. Indicii și predecesorii permit reconstrucția. Lanțurile pe două litere au alte condiții decât cele pe una.', 'a = [2, 2, 2]\nprint("LIS strict: 1; nedescrescător: 3")', 'Pentru a = [2, 2, 2], care este lungimea maximă a unui subșir nedescrescător, în care egalitatea este permisă?', ['1', '2', '3'], 2, 'Valorile egale sunt permise în varianta nedescrescătoare.'),
        card('Rucsac, subset sum și vectori', 'La 0/1 ori subset sum fiecare obiect se folosește cel mult o dată: capacitățile se parcurg descrescător. Pentru monede nelimitate poți reutiliza tipul. La exact un element din fiecare vector, tranzițiile pornesc din nivelul anterior, nu din nivelul curent.', 'dp = [True, False, False, False]\nx = 2\nfor s in range(3, x - 1, -1):\n    dp[s] = dp[s] or dp[s - x]', 'În DP cu un singur vector pentru rucsacul 0/1, de ce parcurgem capacitățile descrescător când procesăm un obiect?', ['Ca obiectul să nu fie refolosit', 'Pentru sortarea numerelor', 'Pentru a evita orice listă'], 0, 'Starea sursă trebuie să fie cea dinainte de obiectul curent.'),
        card('DP pe intervale și matrice', 'Robotul și pătratele de 1 folosesc vecini deja calculați. Jocul pe secvență are dp[l][r] ca diferență garantată pentru jucătorul curent; alegerea unui capăt scade optimul adversarului. Joburile cu durate folosesc timpul drept stare. Precizează timp și memorie pentru fiecare tabel.', 'print("Joc: dp[l][r] = max(a[l]-dp[l+1][r], a[r]-dp[l][r-1])")', 'În jocul în care alegem un capăt, dp[l][r] reprezintă avantajul jucătorului curent față de adversar. De ce scădem dp-ul intervalului rămas din valoarea aleasă?', ['Următorul jucător este adversarul', 'Pentru a sorta lista', 'Ca suma să fie mereu negativă'], 0, 'Starea se exprimă din perspectiva jucătorului care urmează.')],
    'backtracking': [
        card('Stare, validare și revenire', 'Definește componentele soluției, domeniul fiecăreia, condiția de continuare și condiția de acceptare. După recursie anulează exact alegerea făcută. O tăiere este corectă numai dacă ramura eliminată nu poate conține o soluție validă.', 'path = []\npath.append(1)\n# apel recursiv\npath.pop()', 'După path.append(1) și explorarea ramurii, ce rol are path.pop() în exemplul de backtracking?', ['Anulează ultima alegere', 'Șterge toate soluțiile', 'Oprește recursia'], 0, 'Restabilește starea pentru următoarea ramură.'),
        card('Permutări, aranjamente și combinări', 'Permutarea folosește toate valorile distincte într-o ordine. Aranjamentul alege k valori și ordinea contează. Combinarea alege k și ordinea nu contează: impune indici crescători. Anagramele cu litere repetate au nevoie de frecvențe sau reguli contra duplicatelor.', 'print("C(3,2): (1,2), (1,3), (2,3)")', 'La alegerea unei combinări de două elemente din {1, 2, 3}, reprezintă (1, 2) și (2, 1) alegeri diferite?', ['Da', 'Nu'], 1, 'Ordinea nu contează la combinări.'),
        card('Enumerare versus numărare', 'Numărul de soluții și lista tuturor soluțiilor sunt cerințe diferite. La monede, cantitățile pe tip elimină permutările aceleiași plăți. Limita stocului și limita totală M trebuie verificate separat. La submulțimi, tratează și mulțimea vidă și elementul 0.', 'print("S=4, monede 1,2: (4,0), (2,1), (0,2)")', 'Dacă fiecare tip de monedă are un stoc limitat, este garantată și o limită totală M aleasă separat, fără să mai verificăm suma cantităților?', ['Da', 'Nu'], 1, 'M este o restricție suplimentară asupra sumei cantităților.'),
        card('Regine, deranjamente și restricții', 'O soluție pentru regine poate fi vectorul coloanelor pe linii: coloane distincte și |c[i]-c[j]| != |i-j|. La deranjamente exclude valoarea egală poziției. Pentru echipe, chestionare și cifre, formulează numărul elementelor și suma înainte de generare.', 'cols = [2, 4, 1, 3]\nprint(all(abs(cols[i] - cols[j]) != abs(i - j) for i in range(4) for j in range(i)))', 'Pentru două regine aflate pe poziții distincte (r1, c1) și (r2, c2), când se atacă pe diagonală?', ['Diferențele absolute de linii și coloane sunt egale', 'Sunt în coloane diferite', 'Suma coloanelor este pară'], 0, 'Pantele diagonalelor sunt ±1.')],
    'modular': [
        card('Module, import și pachete', 'Un modul propriu este un fișier Python. import nume păstrează accesul prin nume.funcție; from nume import f aduce numele f în spațiul curent. __name__ este __main__ pentru programul rulat direct. Pachetele organizează module în directoare; __init__.py poate inițializa un pachet obișnuit.', 'import math\nprint(math.isqrt(10))', 'În organizarea obișnuită a unui proiect Python, ce este un modul propriu care conține funcții reutilizabile?', ['Un fișier .py', 'Un cont online', 'O variabilă globală obligatorie'], 0, 'Funcțiile reutilizabile pot fi definite într-un fișier separat.'),
        card('Specificații, TDD și refactorizare', 'Scrie intrările admise, rezultatul și cazurile-limită. În TDD: un test care eșuează, implementarea minimă, toate testele, apoi refactorizare. Un test trecut nu demonstrează toate intrările. Refactorizarea schimbă structura internă păstrând comportamentul observabil.', 'def patrat(x):\n    return x * x\nassert patrat(-3) == 9', 'La refactorizare, trebuie schimbat comportamentul observabil al programului pentru aceleași intrări?', ['Da', 'Nu'], 1, 'Ea păstrează comportamentul și îmbunătățește organizarea.'),
        card('Decoratori și funcții wrapper', 'Un decorator primește o funcție și întoarce un comportament nou. wrapper(*args,**kwargs) poate delega apelul păstrând argumentele; return transmite rezultatul. Separă măsurarea sau jurnalizarea de calculul efectiv.', 'def identitate(f):\n    def wrapper(*args, **kwargs):\n        return f(*args, **kwargs)\n    return wrapper', 'În decoratorul din exemplu, cum păstrează wrapper valoarea returnată de funcția f?', ['Să îl returneze dacă interfața îl cere', 'Să îl piardă mereu', 'Să îl sorteze'], 0, 'Altfel funcția decorată ar returna None în locul rezultatului.')],
    'obiecte': [
        card('Clase și instanțe', '__init__ configurează instanța și nu returnează obiectul. self referă instanța apelului. Atributele create pe self sunt ale instanței; o listă mutabilă declarată pe clasă poate fi partajată. Metodele grupează comportamentul și regulile datelor.', 'class Cutie:\n    def __init__(self):\n        self.elemente = []', 'După a = Cutie() și b = Cutie(), sunt a.elemente și b.elemente două liste distincte?', ['Da', 'Nu'], 0, 'Fiecare inițializare construiește o listă nouă.'),
        card('Moștenire și interfețe', 'O clasă derivată poate suprascrie metode și folosi super pentru implementarea clasei de bază. Polimorfismul permite apelul aceleiași metode cost() pe obiecte diferite. Folosește compoziție când relația este „are”, moștenire când substituția este corectă.', 'class Baza:\n    def cost(self):\n        return 10\nclass Redus(Baza):\n    def cost(self):\n        return super().cost() - 2', 'Ce returnează Redus().cost()?', ['10', '8', '2'], 1, 'Metoda suprascrisă reutilizează baza și aplică reducerea.'),
        card('Organizarea aplicației', 'Separă interfața, serviciile/regulile, entitățile și repository-ul. O entitate are identitate; un obiect valoare se descrie prin conținut. Un DTO transportă date fără a concentra toate regulile. Un agregat păstrează invarianta unui grup de obiecte; operațiile externe trec prin rădăcina lui.', 'print("Interfață → Serviciu → Repository")', 'În arhitectura prezentată, ce componentă izolează operațiile de căutare și stocare a înregistrărilor?', ['În repository', 'În fiecare print', 'În denumirea fișierului HTML'], 0, 'Repository-ul izolează modul de stocare de restul aplicației.')]
    }
    for chapter in chapters:
        chapter['studyCards'] = cards[chapter['id']]
        chapter['supplemental'] = chapter.get('supplemental', False)
